-- Somente leitura. Os agregados de negócio devem ficar em armazenamento privado.
BEGIN READ ONLY;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SELECT current_database(),current_user,current_setting('server_version'),current_setting('neon.timeline_id',true),current_timestamp,pg_current_wal_lsn();
SELECT encode(sha256(convert_to((jsonb_build_object(
 'tables',(SELECT jsonb_agg(jsonb_build_array(c.relname,pg_get_userbyid(c.relowner),c.relrowsecurity,c.relacl::text) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r'),
 'columns',(SELECT jsonb_agg(jsonb_build_array(c.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid),a.attidentity,a.attgenerated) ORDER BY c.relname,a.attnum) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relkind='r'),
 'constraints',(SELECT jsonb_agg(jsonb_build_array(t.relname,c.conname,c.contype,c.convalidated,pg_get_constraintdef(c.oid,true)) ORDER BY t.relname,c.conname) FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND c.contype<>'n'),
 'indexes',(SELECT jsonb_agg(jsonb_build_array(t.relname,c.relname,i.indisunique,i.indisvalid,pg_get_indexdef(i.indexrelid)) ORDER BY t.relname,c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public'),
 'schema_acl',(SELECT nspacl::text FROM pg_namespace WHERE nspname='public'),
 'owner_default_acl',(SELECT jsonb_agg(jsonb_build_array(d.defaclnamespace,d.defaclobjtype,d.defaclacl::text) ORDER BY d.defaclnamespace,d.defaclobjtype) FROM pg_default_acl d WHERE d.defaclrole=(SELECT oid FROM pg_roles WHERE rolname=current_user))))::text,'UTF8')),'hex') AS catalog_sha256;
SELECT 'catalog_items' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."catalog_items" t UNION ALL SELECT 'client_contracts' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."client_contracts" t UNION ALL SELECT 'client_notes' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."client_notes" t UNION ALL SELECT 'clients' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."clients" t UNION ALL SELECT 'companies' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."companies" t UNION ALL SELECT 'company_contacts' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."company_contacts" t UNION ALL SELECT 'conversations' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."conversations" t UNION ALL SELECT 'delivery_tasks' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."delivery_tasks" t UNION ALL SELECT 'evolution_instances' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."evolution_instances" t UNION ALL SELECT 'expenses' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."expenses" t UNION ALL SELECT 'messages' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."messages" t UNION ALL SELECT 'notification_states' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."notification_states" t UNION ALL SELECT 'opportunities' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."opportunities" t UNION ALL SELECT 'organizations' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."organizations" t UNION ALL SELECT 'receivables' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."receivables" t UNION ALL SELECT 'reminders' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."reminders" t UNION ALL SELECT 'users' AS table_name,count(*)::bigint AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') AS fingerprint FROM "public"."users" t;
COMMIT;
